const lessons=[{"sentences":[{"speaker":"A","text":"Good morning because my back wheel wobbles when I ride I brought it to your workshop.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.927666666666667},{"speaker":"B","text":"Let us take a quick look at the machine right now to see the exact issue.","position":2,"audioStartSeconds":5.127666666666666,"audioEndSeconds":9.642958333333333},{"speaker":"A","text":"I noticed strange noises yesterday although I oiled the chain before leaving my house.","position":3,"audioStartSeconds":9.842958333333334,"audioEndSeconds":15.101458333333333},{"speaker":"B","text":"The main problem is that several metal spokes are completely loose on the rear rim.","position":4,"audioStartSeconds":15.301458333333333,"audioEndSeconds":20.224916666666665},{"speaker":"A","text":"Can you tighten them today because I need this bicycle for my commute tomorrow?","position":5,"audioStartSeconds":20.424916666666668,"audioEndSeconds":24.999666666666666},{"speaker":"B","text":"We can certainly fix those spokes although it takes about two hours of careful work.","position":6,"audioStartSeconds":25.199666666666666,"audioEndSeconds":30.238333333333333},{"speaker":"A","text":"How much will this complete repair service cost me in total today?","position":7,"audioStartSeconds":30.438333333333333,"audioEndSeconds":34.549166666666665},{"speaker":"B","text":"The labor and adjustment will cost forty pounds if we do not replace the rim.","position":8,"audioStartSeconds":34.74916666666667,"audioEndSeconds":39.65895833333333},{"speaker":"A","text":"That price fits my budget perfectly since I expected a much higher repair bill.","position":9,"audioStartSeconds":39.858958333333334,"audioEndSeconds":45.103791666666666},{"speaker":"B","text":"If you leave the bicycle here now we can finish everything by three o clock.","position":10,"audioStartSeconds":45.30379166666667,"audioEndSeconds":49.85275},{"speaker":"A","text":"That timing works wonderfully because my office shift finishes at four this afternoon.","position":11,"audioStartSeconds":50.05275,"audioEndSeconds":55.516666666666666},{"speaker":"B","text":"Please sign this quick service ticket while I record your telephone contact details.","position":12,"audioStartSeconds":55.71666666666667,"audioEndSeconds":60.81979166666667},{"speaker":"A","text":"Here is my signature and my mobile number for any urgent updates.","position":13,"audioStartSeconds":61.01979166666667,"audioEndSeconds":65.40125},{"speaker":"B","text":"We will send a short text message when your bicycle is fully ready.","position":14,"audioStartSeconds":65.60125,"audioEndSeconds":69.96979166666667},{"speaker":"A","text":"Thank you for your prompt help and friendly customer service this morning.","position":15,"audioStartSeconds":70.16979166666667,"audioEndSeconds":74.55020833333333},{"speaker":"B","text":"You are very welcome and we will see you later this afternoon.","position":16,"audioStartSeconds":74.75020833333333,"audioEndSeconds":78.77770833333334}],"questions":[{"prompt":"Why did the customer bring the bicycle to the workshop today?","options":["The back wheel wobbles during rides.","The owner bought a new chain.","The bell stopped ringing properly."],"answer":"A","evidenceSentence":1,"evidence":"because my back wheel wobbles when I ride I brought it to your workshop.","explanation":"Khách hàng mang xe đến tiệm vì bánh sau bị lắc lư (wobbles) khi đi."},{"prompt":"What is the primary problem with the customer's bicycle?","options":["The chain is completely broken.","Some spokes are loose on the wheel.","The brakes fail to stop safely."],"answer":"B","evidenceSentence":4,"evidence":"The main problem is that several metal spokes are completely loose on the rear rim.","explanation":"Nhân viên cửa hàng giải thích rằng vấn đề chính là một số căm xe (spoke) bị lỏng ở vành sau."},{"prompt":"How long will the repair work take to complete?","options":["One full hour.","About two hours.","Entire afternoon."],"answer":"B","evidenceSentence":6,"evidence":"although it takes about two hours of careful work.","explanation":"Nhân viên kỹ thuật cho biết công việc sửa chữa mất khoảng hai giờ."},{"prompt":"What is the total cost for the repair service?","options":["Forty pounds.","Fifty pounds.","Thirty pounds."],"answer":"A","evidenceSentence":8,"evidence":"The labor and adjustment will cost forty pounds if we do not replace the rim.","explanation":"Chi phí sửa chữa và điều chỉnh là bốn mươi bảng Anh."},{"prompt":"When can the customer collect the repaired bicycle?","options":["By twelve o clock.","By three o clock.","By four o clock."],"answer":"B","evidenceSentence":10,"evidence":"we can finish everything by three o clock.","explanation":"Xe sẽ được sửa xong trước ba giờ chiều."},{"prompt":"What will the workshop do when the bicycle is ready?","options":["Make a phone call.","Send a short text message.","Wait at the front door."],"answer":"B","evidenceSentence":14,"evidence":"We will send a short text message when your bicycle is fully ready.","explanation":"Cửa hàng sẽ gửi một tin nhắn ngắn khi xe đã sẵn sàng."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
